-- Notebook B, written by sim/simulate.py. Load after schema/*.sql and seed/01_reference_data.sql.
-- preset=normal seed=7 days=1 designs_per_week=48 targets=2
-- The sim schema only maps the simulation's names (C12, L40) to database ids; the inventory never reads it.
begin;
create schema sim;
create table sim.cmap (sim_id text primary key, db_id bigint not null unique);
create function sim.setc(s text, i bigint) returns bigint language sql as $$ insert into sim.cmap values (s, i) returning db_id $$;
create function sim.c(s text) returns bigint language sql stable strict as $$ select db_id from sim.cmap where sim_id = s $$;
create table sim.lmap (sim_id text primary key, db_id bigint not null unique);
create function sim.setl(s text, i bigint) returns bigint language sql as $$ insert into sim.lmap values (s, i) returning db_id $$;
create function sim.l(s text) returns bigint language sql stable strict as $$ select db_id from sim.lmap where sim_id = s $$;
create table sim.rmap (sim_id text primary key, db_id bigint not null unique);
create function sim.setr(s text, i bigint) returns bigint language sql as $$ insert into sim.rmap values (s, i) returning db_id $$;
create function sim.r(s text) returns bigint language sql stable strict as $$ select db_id from sim.rmap where sim_id = s $$;
create table sim.emap (sim_id text primary key, db_id bigint not null unique);
create function sim.sete(s text, i bigint) returns bigint language sql as $$ insert into sim.emap values (s, i) returning db_id $$;
create function sim.e(s text) returns bigint language sql stable strict as $$ select db_id from sim.emap where sim_id = s $$;
create table sim.refused (error_id text, message text);
create function sim.setcs(s text[], i bigint[]) returns void language sql as $$ insert into sim.cmap select * from unnest(s, i) $$;
create function sim.try(p_err text, p_stmt text) returns void language plpgsql as $$
begin execute p_stmt; exception when others then insert into sim.refused values (p_err, sqlerrm); end $$;
